        else:
            fx = -42.0  # Push left
    else:
        # If already at target height, adjust horizontal position
        if target_x_min <= pos.x <= target_x_max:
            # Apply force opposite to velocity to slow down at target
            fx = max(-42.0, min(-vx * 10.0, 42.0))
