        # Apply impulse in direction towards pivot to overcome dead zone
        if pos.x < 10.0:
            sandbox.apply_impulse_to_seat(impulse_mag, fy)
        else:
            sandbox.apply_impulse_to_seat(-impulse_mag, fy)
    else:
        # Apply force when sufficient horizontal speed is present
        sandbox.apply_force_to_seat(fx, fy)

